import Foundation

/// Liftr's localization: English (keys), Dutch (written inline next to the English) and every other
/// European language from `liftr-<code>.json` tables, generated by tools/build_translations.py.
///
/// The language follows the app language chosen by the system (Settings → Liftr → Language);
/// anything not translated falls back to English.
enum L10n {
    /// European languages Liftr ships, besides English and Dutch.
    static let tableLanguages = [
        "bg", "ca", "cs", "da", "de", "el", "es", "et", "fi", "fr", "ga", "hr", "hu", "is", "it", "lt", "lv",
        "mk", "mt", "nb", "pl", "pt-PT", "ro", "ru", "sk", "sl", "sq", "sr", "sv", "tr", "uk",
    ]

    static let language: String = {
        let first = Bundle.main.preferredLocalizations.first ?? "en"
        return normalize(first)
    }()

    static func normalize(_ code: String) -> String {
        let lower = code.lowercased()
        if lower.hasPrefix("nl") { return "nl" }
        if lower.hasPrefix("pt") { return "pt-PT" }
        if lower.hasPrefix("nb") || lower.hasPrefix("no") || lower.hasPrefix("nn") { return "nb" }
        if lower.hasPrefix("sr") { return "sr" }
        let base = String(lower.prefix { $0 != "-" && $0 != "_" })
        return tableLanguages.contains(base) ? base : "en"
    }

    static var isDutch: Bool { language == "nl" }

    static var locale: Locale {
        switch language {
        case "en": Locale(identifier: "en_GB")
        case "nl": Locale(identifier: "nl_NL")
        default: Locale(identifier: language)
        }
    }

    /// The translation table for the current language (empty for English and Dutch).
    static let table: [String: String] = {
        guard language != "en", language != "nl",
              let url = Bundle.main.url(forResource: "liftr-\(language)", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let dict = try? JSONDecoder().decode([String: String].self, from: data) else { return [:] }
        return dict
    }()

    static func lookup(_ en: String, _ nl: String) -> String {
        switch language {
        case "en": en
        case "nl": nl
        default: table[en] ?? en
        }
    }

    /// Name of a built-in exercise in the current language.
    static func exerciseName(id: String, en: String, nl: String) -> String {
        switch language {
        case "en": en
        case "nl": nl
        default: table["exercise." + id] ?? en
        }
    }

    enum WeekdayStyle { case veryShort, short }

    /// Weekday names Monday first, in the app language.
    static func weekdaySymbols(_ style: WeekdayStyle) -> [String] {
        var cal = Calendar(identifier: .gregorian)
        cal.locale = locale
        let symbols = style == .veryShort ? cal.veryShortStandaloneWeekdaySymbols : cal.shortStandaloneWeekdaySymbols
        guard symbols.count == 7 else { return ["M", "T", "W", "T", "F", "S", "S"] }
        return Array(symbols[1...]) + [symbols[0]]
    }
}

/// The text in the app language. Pass the English and the Dutch text; other languages come from the tables.
func tr(_ en: String, _ nl: String) -> String {
    L10n.lookup(en, nl)
}

/// Same as `tr`, with values for the placeholders {1}, {2}, … (each language may put them in its own order).
func trf(_ en: String, _ nl: String, _ args: Any...) -> String {
    var text = L10n.lookup(en, nl)
    for (index, arg) in args.enumerated() {
        text = text.replacingOccurrences(of: "{\(index + 1)}", with: "\(arg)")
    }
    return text
}
